import { open } from "node:fs/promises";

import { putObject } from "../storage/client.js";

const CHUNK_SIZE = 1024 * 1024;

/**
 * Stream a local file into object storage in fixed-size chunks.
 */
export async function uploadFile(path: string, key: string): Promise<number> {
  const handle = await open(path, "r");
  const buffer = Buffer.alloc(CHUNK_SIZE);
  let position = 0;
  let uploaded = 0;
  while (true) {
    const { bytesRead } = await handle.read(buffer, 0, CHUNK_SIZE, position);
    if (bytesRead === 0) {
      break;
    }
    await putObject(key, buffer.subarray(0, bytesRead), { offset: position });
    position += bytesRead;
    uploaded += bytesRead;
  }
  await handle.close();
  return uploaded;
}
